fn check(n: i32) -> Result<i32, String> {
    if n > 0 {
        Ok(n)
    } else {
        Err(String::from("bad"))
    }
}

fn main() {
    println!("{:?} {:?}", check(3), check(-3));
}

fn main() {
    let a = "4".parse::<i32>();
    let b = a * 2;
    println!("{b}");
}

fn half(s: &str) -> Result<i32, String> {
    match s.parse::<i32>() {
        Ok(n) => {
            if n % 2 == 0 {
                Ok(n / 2)
            } else {
                Err(format!("{n} is odd"))
            }
        }
        Err(_) => Err(String::from("nan")),
    }
}

fn main() {
    for s in ["8", "7", "x"] {
        match half(s) {
            Ok(v) => print!("{v} "),
            Err(e) => print!("[{e}] "),
        }
    }
}
